import {useRouteParams} from '@github-ui/react-core/future/use-route-params'
import {threadViewRoute} from '../routes/thread-view-route'
import {useQuery} from '@github-ui/react-query'
import {useTraceManager} from '@github-ui/copilot-chat/components/tracing/TraceManagerContext'

export function useCoffeTrace() {
  const {thread_id: threadId} = useRouteParams(threadViewRoute)
  const manager = useTraceManager()

  const query = useQuery({
    queryKey: ['trace', threadId],
    queryFn: async () => {
      const result = await manager.fetchCoffeTrace(threadId)
      if (result.ok) {
        return result
      } else {
        throw new Error(`Failed to fetch trace: ${result.status} ${result.error}`)
      }
    },
  })

  return {query, threadId}
}
